import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const requiredFields = ['id', 'job', 'attempt', 'seq', 'type'];

export function reduceEvents(text) {
  if (typeof text !== 'string') throw new Error('Input must be a string');

  const events = new Map();
  let duplicates = 0;
  for (const [index, line] of text.split('\n').entries()) {
    if (line.trim() === '') continue;
    let event;
    try {
      event = JSON.parse(line);
    } catch {
      throw new Error(`Invalid JSON on line ${index + 1}`);
    }
    if (
      event === null || typeof event !== 'object' || Array.isArray(event) ||
      !requiredFields.every(field => Object.hasOwn(event, field)) ||
      typeof event.id !== 'string' || event.id.length === 0 ||
      typeof event.job !== 'string' || event.job.length === 0 ||
      !Number.isSafeInteger(event.attempt) || event.attempt < 1 ||
      !Number.isSafeInteger(event.seq) || event.seq < 0 ||
      !['started', 'succeeded', 'failed'].includes(event.type)
    ) {
      throw new Error(`Invalid event on line ${index + 1}`);
    }

    if (events.has(event.id)) {
      const previous = events.get(event.id);
      if (!requiredFields.every(field => previous[field] === event[field])) {
        throw new Error(`Conflicting event ID: ${JSON.stringify(event.id)}`);
      }
      duplicates++;
    } else {
      events.set(event.id, event);
    }
  }

  const jobs = new Map();
  for (const event of events.values()) {
    if (!jobs.has(event.job)) jobs.set(event.job, new Map());
    const attempts = jobs.get(event.job);
    if (!attempts.has(event.attempt)) {
      attempts.set(event.attempt, { start: null, terminal: null });
    }
    const state = attempts.get(event.attempt);
    const slot = event.type === 'started' ? 'start' : 'terminal';
    if (state[slot] !== null) {
      throw new Error(`Repeated ${slot} for job ${JSON.stringify(event.job)}, attempt ${event.attempt}`);
    }
    state[slot] = event;
  }

  const report = [];
  for (const [job, attempts] of jobs) {
    const rows = [];
    for (const [attempt, { start, terminal }] of attempts) {
      if (start === null) {
        throw new Error(`Missing start for job ${JSON.stringify(job)}, attempt ${attempt}`);
      }
      if (terminal !== null && terminal.seq <= start.seq) {
        throw new Error(`Terminal must follow start for job ${JSON.stringify(job)}, attempt ${attempt}`);
      }
      rows.push({
        attempt,
        status: terminal === null ? 'running' : terminal.type,
        startedSeq: start.seq,
        finishedSeq: terminal === null ? null : terminal.seq,
      });
    }
    rows.sort((a, b) => a.attempt - b.attempt);
    report.push({ job, attempts: rows });
  }
  report.sort((a, b) => a.job < b.job ? -1 : a.job > b.job ? 1 : 0);
  return { jobs: report, duplicates };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node receipt-report.js LOGFILE');
    const report = reduceEvents(readFileSync(process.argv[2], 'utf8'));
    process.stdout.write(`${JSON.stringify(report)}\n`);
  } catch (error) {
    process.stderr.write(`${error.message}\n`);
    process.exitCode = 2;
  }
}

