+    [start, { ...done, seq: 0 }],
+    [{ ...start, seq: 2 }, done],
+  ]) assert.throws(() => reduceEvents(jsonl(events)), Error);
+});
+
+test('preserves string keys, uses UTF-16 sorting, and permits overlapping attempts', () => {
+  const names = ['\uE000', '😀', '__proto__', ' x ', 'A'];
+  const events = names.map((job, index) => ({ ...start, id: String(index), job }));
+  events.push({ ...start, id: '__proto__', job: ' x ', attempt: 10 });
+  events.push({ ...start, id: 'finish', job: ' x ', seq: 1, type: 'failed' });
+  const report = reduceEvents(`\n ${'\r\n'}${jsonl(events)}\r\n\t`);
+  assert.deepEqual(report.jobs.map(row => row.job), [' x ', 'A', '__proto__', '😀', '\uE000']);
+  assert.deepEqual(report.jobs[0].attempts, [
+    { attempt: 1, status: 'failed', startedSeq: 0, finishedSeq: 1 },
+    { attempt: 10, status: 'running', startedSeq: 0, finishedSeq: null },
+  ]);
+});
+
+test('CLI has exact success output and failures produce only stderr with exit 2', () => {
+  const directory = mkdtempSync(join(tmpdir(), 'receipt-report-'));
+  const script = fileURLToPath(new URL('../receipt-report.js', import.meta.url));
+  const input = join(directory, 'events.jsonl');
+  const run = args => spawnSync(process.execPath, [script, ...args], { encoding: 'utf8' });
+  try {
+    writeFileSync(input, jsonl([start]));
+    const success = run([input]);
+    assert.equal(success.status, 0);
+    assert.equal(success.stderr, '');
+    assert.equal(success.stdout, JSON.stringify(reduceEvents(jsonl([start]))) + '\n');
+    for (const args of [[], [input, input], [join(directory, 'missing')]]) {
+      const result = run(args);
+      assert.equal(result.status, 2);
+      assert.equal(result.stdout, '');
+      assert.ok(result.stderr.trim());
+    }
+    for (const text of ['{bad', jsonl([start, { ...start, id: 'other' }])]) {
+      writeFileSync(input, text);
+      const result = run([input]);
+      assert.equal(result.status, 2);
+      assert.equal(result.stdout, '');
+      assert.ok(result.stderr.trim());
+    }
+    const imported = spawnSync(process.execPath, ['--input-type=module', '-e',
+      `import ${JSON.stringify(new URL('../receipt-report.js', import.meta.url).href)}`,
+    ], { encoding: 'utf8' });
+    assert.equal(imported.status, 0);
+    assert.equal(imported.stdout, '');
+    assert.equal(imported.stderr, '');
+  } finally {
+    rmSync(directory, { recursive: true, force: true });
+  }
+});

